import { REAL_ENGINES } from './engine-catalog';
import { FAIRING_PARTS, TANK_PARTS, assembledTanks, fitTank, removeTank, tankPart } from './parts';
import '@fontsource/barlow-condensed/latin-500.css';
import '@fontsource/barlow-condensed/latin-600.css';
import '@fontsource/ibm-plex-mono/latin-400.css';
import './orbital.css';
import { ENGINES3D, EARTH, FUELS, MATERIALS, OBJECTIVES, analyzeVehicle, clamp, defaultVehicle, engineSpec, fuelCapacity, fuelMass, fairingMass, inspectVehicle, newStage, validVehicle, vehicleCost, vehicleHeight, type Vehicle, type Objective } from './model';
import { altitude3D, createFlight3D, deltaV3D, jettisonFairing, missionGrade, orbitState, separate3D, simulate3D, stepFlight3D, stopFlight, telemetry3D, type Flight3D } from './simulation';
import { OrbitalScene } from './scene';
import { FlightAudio } from './audio';
import { read3D, parse3D, recordFlight, write3D, type Report3D } from './storage';

const host=document.getElementById('app')!;
host.innerHTML='<canvas id="world" aria-label="三维火箭制造与连续飞行场景" tabindex="0"></canvas><div id="interface"></div><div id="notifications" aria-live="polite"></div>';
const canvas=document.getElementById('world') as HTMLCanvasElement,ui=document.getElementById('interface')!;
let save=read3D(),view:'workshop'|'flight'='workshop',selected=0,modal='',panelTab='build',cameraMode='chase',cutaway=false,simulation=true,recorded=false,report:Report3D|null=null;
let flight:Flight3D|null=null,speed=1,hiddenUI=false,undo:Vehicle[]=[],redo:Vehicle[]=[],bench:BenchResult[]=[],busy=false;
let scene:OrbitalScene|null=null;let engineDetail='merlin-1d',partsCategory='tanks';
const audio=new FlightAudio();
const $=(id:string)=>document.getElementById(id);
const esc=(value:unknown)=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const n=(v:number,d=0)=>Number.isFinite(v)?v.toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d}):'—';
const money=(v:number)=>`₡ ${n(v)}`;
const time=(t:number)=>`${t<0?'−':'+'}${String(Math.floor(Math.abs(t)/60)).padStart(2,'0')}:${String(Math.floor(Math.abs(t)%60)).padStart(2,'0')}`;
const stars=(v:number)=>`<span class="stars" aria-label="${v} 颗星">${'★'.repeat(v)}<span>${'☆'.repeat(3-v)}</span></span>`;
const objective=()=>OBJECTIVES.find(o=>o.id===save.objective)!;
const phaseName:Record<string,string>={countdown:'发射倒计时',ascent:'动力上升',coast:'无推力滑行',insertion:'轨道圆化',orbit:'地球轨道',failed:'飞行结束'};
interface BenchResult {name:string;vehicle:Vehicle;flight:Flight3D;}
try{scene=new OrbitalScene(canvas,save.vehicle);scene.onSelect=i=>{selected=i;scene!.setSelected(i);render();};canvas.addEventListener('rendererror',e=>{if(flight)flight.paused=true;notify((e as CustomEvent).detail);render();});}catch(e){console.error(e);host.innerHTML='<section class="gpu-error"><h1>需要支持 WebGL 2 的浏览器</h1><p>3D 场景初始化失败。请开启浏览器硬件加速，使用支持 WebGL 2 的 Chrome、Edge 或 Safari 后重试。</p><button onclick="location.reload()">重新加载</button></section>';}
function persist(){if(!write3D(save))notify('本机存储空间不足。请导出存档，并清理较早的飞行记录。');}
function snapshot(){if(flight&&view==='flight')save.active={flight,simulation,recorded};else delete save.active;persist();}
function notify(text:string){const el=document.createElement('div');el.className='notification';el.textContent=text;$('notifications')!.append(el);setTimeout(()=>el.remove(),4500);}
function mutate(fn:(v:Vehicle)=>void){const next=structuredClone(save.vehicle);fn(next);if(JSON.stringify(next)===JSON.stringify(save.vehicle))return;if(!validVehicle(next)){notify('参数超出制造范围。');return;}undo.push(structuredClone(save.vehicle));undo=undo.slice(-30);redo=[];save.vehicle=next;selected=Math.min(selected,next.stages.length-1);scene?.setVehicle(next);scene?.setSelected(selected);persist();render();}
function icon(type:string){const p:Record<string,string>={cube:'<path d="m12 3 9 5v9l-9 5-9-5V8zM3 8l9 5 9-5M12 13v9"/>',launch:'<path d="m9 15 1-8 4-4 3 5-1 8-4-2zM10 14l-4 4 4-1m5-2 2 4-3-2M10 19l-2 3"/>',archive:'<path d="M4 5h16v4H4zM6 9v12h12V9M10 13h4"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12"/><circle cx="12" cy="12" r="3"/>',play:'<path d="m9 5 11 7-11 7z"/>',pause:'<path d="M9 5v14M15 5v14"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>'};return `<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p[type]||p.arrow}</svg>`;}
function render(){
 if(!scene)return;
 ui.className=hiddenUI?'cinematic':'';
 ui.innerHTML=`<header class="masthead"><button class="wordmark" data-action="workshop"><span class="brand-arrow">↗</span><span>MERIDIAN<small>GO TO MARS / 地球轨道计划</small></span><em>3D</em></button><nav aria-label="主导航"><button class="${view==='workshop'?'active':''}" data-action="workshop">${icon('cube')} 制造车间</button><button class="${view==='flight'?'active':''}" data-action="${view==='flight'?'flight':'brief'}">${icon('launch')} ${view==='flight'?'飞行控制':'发射评审'}</button><button data-action="archive">${icon('archive')} 飞行档案</button></nav><div class="header-right"><span class="earth-chip"><i></i> EARTH ORBITAL PROGRAM</span><button class="header-button" data-action="audio" aria-label="${save.muted?'开启声音':'关闭声音'}">${save.muted?'◌':'♫'}</button><button class="header-button help-button" data-action="help" aria-label="工程手册">?</button></div></header>
 ${view==='workshop'?workshopUI():flightUI()}<div class="scene-toolbar ${view==='flight'?'flight-toolbar':''}">${view==='workshop'?`<button class="${cutaway?'active':''}" data-action="cutaway">${icon('eye')} 储箱剖视</button><span></span><button data-action="engine-close">发动机近景</button><button data-action="reset-camera">整箭视角</button><button data-action="cinematic">纯场景 <kbd>H</kbd></button>`:`${[['chase','追踪'],['cinema','电影'],['orbit','轨道'],['wide','远景']].map(([id,label])=>`<button data-camera="${id}" class="${cameraMode===id?'active':''}">${label}</button>`).join('')}<span></span><button data-action="cinematic">隐藏界面 <kbd>H</kbd></button>`}</div>
 <div class="scene-caption"><span>${view==='workshop'?'VEHICLE ASSEMBLY FACILITY / BAY 01':flight?.phase==='orbit'?'LOW EARTH ORBIT / 地球近地轨道':'CAPE MERIDIAN / 发射场 01'}</span><span id="scene-readout">${view==='workshop'?'拖动旋转 · 滚轮缩放 · 点击箭体选级':'同一飞行器 · 连续轨迹 · 真实地球尺度'}</span></div><div class="graphics-status"><span><i></i> WEBGL 2 · PBR</span><span id="fps">— FPS</span></div>${modal?modalUI():''}`;
 if(modal){ui.querySelectorAll<HTMLElement>('.masthead,.workshop-left,.properties,.design-console,.flight-left,.flight-right,.flight-bottom,.scene-toolbar').forEach(el=>el.inert=true);ui.querySelector<HTMLButtonElement>('.modal button')?.focus();}
 updateTelemetry();
}
function workshopUI(){const v=save.vehicle,a=analyzeVehicle(v),s=v.stages[selected],e=engineSpec(s),findings=inspectVehicle(v,objective());return `<section class="workshop-title"><p class="eyebrow">BUILD SOMETHING THAT STAYS UP THERE.</p><h1>从一张蓝图，到一条轨道<span>。</span></h1></section>
 <aside class="workshop-left glass"><div class="panel-header"><span>飞行器总装</span><small>ASSEMBLY</small></div><label class="field-label" for="vehicle-name">型号名称</label><input id="vehicle-name" value="${esc(v.name)}" maxlength="60"><div class="section-heading"><span>分级结构</span><small>顶部是载荷，底部先点火</small></div><div class="vehicle-tree"><div class="payload-node"><span class="tree-icon">◇</span><div><strong>有效载荷</strong><small>${n(v.payload)} kg · ${v.fairing?'气动整流罩':'裸露载荷'}</small></div></div>${v.stages.map((st,i)=>({st,i})).reverse().map(({st,i})=>`<button class="stage-node ${i===selected?'selected':''}" data-stage="${i}"><span class="tree-icon">${String(i+1).padStart(2,'0')}</span><span><strong>第 ${i+1} 级 <em>${i===0?'BOOSTER':'UPPER STAGE'}</em></strong><small>${engineSpec(st).name.split(' ')[1]} ×${st.engines} · ${(fuelMass(st)/1000).toFixed(1)} t 推进剂</small></span><b>↗</b></button>`).join('')}</div><div class="stage-actions"><button data-action="add-stage" ${v.stages.length>=3?'disabled':''}>＋ 添加上面级</button><button data-action="delete-stage" ${v.stages.length===1?'disabled':''}>移除选中级</button></div><button class="quiet-button starter-button" data-action="starter">新建标准件参考构型 ↗</button><div class="section-heading"><span>任务与载荷</span></div><label class="field-label" for="objective">当前任务</label><select id="objective">${OBJECTIVES.map(o=>`<option value="${o.id}" ${o.id===save.objective?'selected':''}>${o.name}${save.records[o.id]?' · '+save.records[o.id].stars+'★':''}</option>`).join('')}</select>${range('有效载荷','payload',v.payload,100,20000,50,'kg')}<label class="switch-row"><span>载荷整流罩<small>增加 ${fairingMass(v)} kg，降低阻力和热输入</small></span><input id="fairing" type="checkbox" ${v.fairing?'checked':''}></label><button class="quiet-button program-button" data-action="guidance">飞行程序与转弯设置 ↗</button><div class="checklist-heading">设计检查 <span>${findings.filter(f=>f.level==='error').length} 项阻断 / ${findings.filter(f=>f.level==='warning').length} 项提示</span></div><div class="findings">${findings.map(f=>`<button class="finding ${f.level}" ${f.stage!==undefined?`data-stage="${f.stage}"`:'data-action="brief"'}><span>${f.level==='ok'?'✓':f.level==='error'?'!':'△'}</span><span><strong>${f.title}</strong><small>${f.detail}</small></span></button>`).join('')}</div></aside>
 <aside class="properties glass"><div class="panel-header"><span>第 ${selected+1} 级 · 工程配置</span><small>STAGE ${String(selected+1).padStart(2,'0')}</small></div><div class="property-tabs"><button data-property="build" class="${panelTab==='build'?'active':''}">制造参数</button><button data-property="performance" class="${panelTab==='performance'?'active':''}">质量与供给</button></div>${panelTab==='build'?`<div class="section-heading"><span>推进系统</span><small>ENGINE SELECTION</small></div><div class="engine-list">${[e,...REAL_ENGINES.filter(en=>en.id!==s.engine&&en.fuel===s.fuel)].slice(0,4).map(en=>`<button class="engine-option ${en.id===s.engine?'selected':''}" data-engine="${en.id}"><span><strong>${en.name}</strong><small>${en.role} · ${FUELS[en.fuel].name}</small></span><b>${en.provenance?.published.ispVac===undefined?'≈':''}${n(en.ispVac,0)}<small>s</small></b></button>`).join('')}</div><button class="library-open" data-action="engine-library">真实发动机资料库 <span>${REAL_ENGINES.length} 型 · 参数与出处 ↗</span></button><p class="property-note">${e.description}</p><div class="engine-quantity"><span>发动机数量<small>推力、干重与安装面积同步增加</small></span><div><button data-count="-1" aria-label="减少发动机" ${s.engines===1?'disabled':''}>−</button><strong>${s.engines}</strong><button data-count="1" aria-label="增加发动机" ${s.engines===9?'disabled':''}>＋</button></div></div>${tankAssemblyUI()}<details class="custom-tank"><summary>高级：改装箱体几何</summary><p class="property-note">更改尺寸会将标准件组合改成定制储箱。</p>${range('直径','diameter',s.diameter,1,6,.1,'m')}${range('筒段长度','tank-length',s.tankLength,1,25,.5,'m')}</details>${range('推进剂加注','fill',s.fill*100,10,100,1,'%')}<div class="inline-metrics"><span>可用容积 <b>${n(a.stages[selected].volume,1)} m³</b></span><span>推进剂 <b>${n(fuelMass(s)/1000,2)} t</b></span></div><label class="field-label" for="material">结构材料</label><select id="material">${Object.entries(MATERIALS).map(([id,m])=>`<option value="${id}" ${s.material===id?'selected':''}>${m.name}</option>`).join('')}</select><p class="property-note">${MATERIALS[s.material].description}</p><label class="field-label" for="fuel-type">储箱推进剂</label><select id="fuel-type">${Object.entries(FUELS).map(([id,f])=>`<option value="${id}" ${s.fuel===id?'selected':''}>${f.name} · ${f.density} kg/m³</option>`).join('')}</select>${e.fuel!==s.fuel?'<button class="match-fuel" data-action="match-fuel">⚠ 推进剂不兼容 · 匹配发动机供给</button>':''}<label class="switch-row"><span>标准稳定尾翼<small>气动力矩参与姿态仿真</small></span><input id="fins" type="checkbox" ${s.fins?'checked':''}></label>`:performancePanel()}
 </aside><section class="design-console glass"><div class="console-metric"><span>理论机动能力 <small>VACUUM Δv</small></span><strong>${n(a.dv/1000,2)}<em>km/s</em></strong><div class="metric-track"><i style="width:${Math.min(100,a.dv/12000*100)}%"></i></div></div><div class="console-metric"><span>发射质量 / 海平面推重比</span><strong>${n(a.mass/1000,1)}<em>t</em><b class="twr ${a.stages[0].twr<1?'bad':''}">${n(a.stages[0].twr,2)} <small>TWR</small></b></strong><p>${n(a.height,1)} m 高 · ${v.stages.length} 级 · 质心距底部 ${n(a.com,1)} m</p></div><div class="console-actions"><div><span>制造费用</span><strong>${money(a.cost)}</strong><button class="quiet-button" data-action="blueprint">保存蓝图</button></div><div class="launch-buttons"><button class="secondary" data-action="bench">试验台</button><button class="primary" data-action="brief">任务评审 ${icon('arrow')}</button></div></div></section><div class="edit-history"><button data-action="undo" ${undo.length?'':'disabled'} aria-label="撤销">↶</button><button data-action="redo" ${redo.length?'':'disabled'} aria-label="重做">↷</button></div>`;}
function range(label:string,id:string,value:number,min:number,max:number,step:number,unit:string,disabled=false){return `<label class="range-label" for="${id}"><span>${label}</span><strong>${n(value,value<10?1:0)} <small>${unit}</small></strong></label><input id="${id}" type="range" ${disabled?'disabled':''} min="${min}" max="${max}" step="${step}" value="${value}">`;}
function performancePanel(){const v=save.vehicle,s=v.stages[selected],a=analyzeVehicle(v),perf=a.stages[selected],e=engineSpec(s),match=e.fuel===s.fuel;return `<div class="section-heading"><span>推进剂供给链</span><small>FUEL FLOW</small></div><div class="flow-diagram ${match&&s.valve?'':'broken'}"><div><span>储箱</span><strong>${FUELS[s.fuel].name}</strong><small>${n(fuelMass(s)/1000,2)} t</small></div><b>↓</b><button data-action="valve"><span>主供给阀</span><strong>${s.valve?'OPEN / 已打开':'CLOSED / 已关闭'}</strong></button><b>↓</b><div><span>${e.name}</span><strong>${match?'燃料兼容':'燃料不兼容'}</strong><small>${s.engines} 台 · ${(e.vac*s.engines/1000).toFixed(0)} kN 真空推力</small></div></div><p class="property-note">阀门状态和推进剂类型直接决定发动机能否工作。关闭阀门后试飞，可以观察供给中断。</p><div class="section-heading"><span>分级分析</span></div><dl class="technical-list"><div><dt>本级推进剂</dt><dd>${n(perf.fuel/1000,2)} t</dd></div><div><dt>本级干重</dt><dd>${n(perf.dry/1000,2)} t</dd></div><div><dt>点火时总质量</dt><dd>${n(perf.wet/1000,2)} t</dd></div><div><dt>真空比冲</dt><dd>${e.ispVac} s</dd></div><div><dt>海平面比冲</dt><dd>${e.ispSea} s</dd></div><div><dt>本级真空 Δv</dt><dd>${n(perf.dv)} m/s</dd></div><div><dt>全推力燃烧</dt><dd>${n(perf.burn)} s</dd></div><div><dt>真空推重比</dt><dd>${n(perf.vacTwr,2)}</dd></div><div><dt>摆角能力</dt><dd>±${e.gimbal}°</dd></div><div><dt>最小节流</dt><dd>${n(e.minThrottle*100)}%</dd></div></dl><div class="section-heading"><span>整箭质量分配</span></div><div class="mass-stack">${v.stages.map((st,i)=>`<div><span>第 ${i+1} 级</span><i style="width:${(a.stages[i].fuel+a.stages[i].dry)/a.mass*100}%"></i><b>${n((a.stages[i].fuel+a.stages[i].dry)/1000,1)} t</b></div>`).join('')}</div>`;}
function flightUI(){const f=flight!;return `<div class="flight-top-label"><span class="live-dot"></span><span>${simulation?'SIMULATION / 工程验证':'LIVE MISSION / 正式飞行'}</span><strong>${esc(f.vehicle.name)}</strong></div><aside class="flight-left glass"><div class="mission-timer"><span>MISSION ELAPSED TIME</span><strong id="mission-clock">T ${time(f.time)}</strong><div><span id="flight-phase">${phaseName[f.phase]}</span><i>${f.paused?'已暂停':'TELEMETRY LIVE'}</i></div></div><div class="phase-sequence">${['countdown','ascent','coast','insertion','orbit'].map((id,i)=>`<div data-phase="${id}" class="${id===f.phase?'active':''}"><span>0${i+1}</span><strong>${phaseName[id]}</strong></div>`).join('')}</div><div class="section-heading"><span>地面控制日志</span></div><div class="mission-events" id="events"></div><div class="flight-objective"><small>MISSION OBJECTIVE</small><strong>${f.objective.name}</strong><p>${n(f.objective.payload/1000,1)} t 载荷 → ${n(f.objective.altitude/1000)} km 轨道</p></div></aside>
 <aside class="flight-right glass"><div class="panel-header"><span>飞行遥测</span><small>REAL-TIME</small></div><div id="flight-metrics"></div><div class="attitude-display"><canvas id="attitude" width="220" height="150" aria-label="实际姿态与当地水平线"></canvas><div><span id="attitude-label">—°</span><small>相对当地竖直</small></div></div><div id="stage-fuel"></div><label class="switch-row"><span>自动驾驶<small>飞行程序可随时接管</small></span><input id="autopilot" type="checkbox" ${f.autopilot?'checked':''}></label><div class="manual-inputs ${f.autopilot?'locked':''}">${range('节流指令','throttle',f.command*100,0,100,1,'%',f.autopilot)}${range('俯仰','pitch',f.manualPitch*180/Math.PI,-10,100,1,'°',f.autopilot)}${range('偏航','yaw',f.manualYaw*180/Math.PI,-30,30,1,'°',f.autopilot)}</div><div class="manual-actions"><button class="secondary" data-action="separate">分级 <kbd>SPACE</kbd></button><button class="secondary" data-action="fairing">抛罩 <kbd>F</kbd></button></div></aside>
 <section class="flight-bottom glass"><div class="orbital-elements" id="orbit-elements"></div><div class="flight-time-controls"><button class="pause-button" data-action="pause" aria-label="${f.paused?'继续飞行':'暂停飞行'}">${icon(f.paused?'play':'pause')}</button><div class="warp-buttons">${[1,5,20,50].map(x=>`<button class="${speed===x?'active':''}" data-warp="${x}">${x}×</button>`).join('')}</div><span class="physics-note">固定 0.025 s 物理子步长</span><button class="${f.reason?'primary':'secondary'}" data-action="${f.reason?'report':'abort'}">${f.reason?'飞行复盘 ↗':'终止飞行'}</button></div></section>${f.reason?`<div class="flight-result ${f.phase==='orbit'?'success':'failure'}"><span>${f.phase==='orbit'?'ORBIT CONFIRMED':'FLIGHT TERMINATED'}</span><strong>${f.phase==='orbit'?'欢迎来到地球轨道。':'这一次，留给下一次。'}</strong>${stars(missionGrade(f).stars)}<small>${f.phase==='orbit'?'轨道继续传播 · 可切换轨道视角观察':'打开复盘，查看首个失效事件与飞行损失'}</small></div>`:''}`;}
function modalUI(){
 const close=`<button class="modal-close" data-action="close" aria-label="关闭">${icon('close')}</button>`;
 if(modal==='engines')return engineLibraryUI(close);
 if(modal==='parts')return partsLibraryUI(close);
 if(modal==='brief'){const o=objective(),a=analyzeVehicle(save.vehicle),checks=inspectVehicle(save.vehicle,o);return `<div class="modal-backdrop"><section class="modal briefing-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">${close}<p class="eyebrow">FLIGHT READINESS REVIEW / 发射评审</p><h2 id="modal-title">${o.name}<span>↗</span></h2><p class="modal-description">${o.description}</p><div class="mission-specs"><div><small>有效载荷</small><strong>${n(o.payload/1000,1)} t</strong></div><div><small>目标轨道</small><strong>${n(o.altitude/1000)} km</strong></div><div><small>制造预算</small><strong>${money(o.budget)}</strong></div></div><div class="review-layout"><div><h3>工程验收</h3><ul class="review-checks"><li>近地点 ≥ ${n((o.altitude-20000)/1000)} km，远地点 ≤ ${n((o.altitude+60000)/1000)} km</li><li>轨道偏心率 &lt; 0.012，无推力验证 8 s</li><li>载荷 ≥ ${n(o.payload)} kg，额外星奖励预算与余量</li></ul><div class="review-design"><span>${esc(save.vehicle.name)}</span><strong>${n(a.mass/1000,1)} t / ${n(a.height,1)} m / ${n(a.dv/1000,2)} km/s</strong></div><p class="property-note">从发射场到轨道，全程使用同一飞行器和实际燃料状态。模拟与正式飞行使用相同物理；只有正式飞行记录任务星级。</p></div><div><h3>发射前检查</h3>${checks.map(c=>`<div class="review-finding ${c.level}"><b>${c.level==='ok'?'✓':c.level==='error'?'!':'△'}</b><span><strong>${c.title}</strong><small>${c.detail}</small></span></div>`).join('')}</div></div><div class="modal-actions"><button class="secondary" data-action="launch-sim">${icon('play')} 模拟试飞</button><button class="primary" data-action="launch-live">进入发射序列 ${icon('arrow')}</button></div></section></div>`;}
 if(modal==='guidance'){const g=save.vehicle.guidance;return `<div class="modal-backdrop"><section class="modal slim" role="dialog" aria-modal="true" aria-labelledby="modal-title">${close}<p class="eyebrow">GUIDANCE & CONTROL / 飞行程序</p><h2 id="modal-title">给火箭一条合适的路。</h2><p class="modal-description">飞行程序决定何时向水平转弯。转得过早会掉回大气，过晚会消耗过多重力损失。</p>${range('转弯起点','turn-start',g.turnStart,200,5000,50,'m')}${range('接近水平高度','turn-end',g.turnEnd,35000,110000,1000,'m')}${range('推力加速度上限','max-g',g.maxG,2,5,.1,'g')}<label class="switch-row"><span>燃料耗尽自动分级<small>分离后等待 1.2 s，再开始点火爬升</small></span><input id="auto-stage" type="checkbox" ${g.autoStage?'checked':''}></label><div class="callout">上面级推重比较低时，一级需要建立更高的远地点，让上面级有时间完成水平加速。</div><button class="primary wide" data-action="close">保存飞行程序</button></section></div>`;}
 if(modal==='bench')return benchUI(close);
 if(modal==='report'&&report)return reportUI(report,close);
 if(modal==='archive')return `<div class="modal-backdrop"><section class="modal archive-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">${close}<p class="eyebrow">FLIGHT HERITAGE / 工程档案</p><h2 id="modal-title">每一次飞行，都有来路。</h2><div class="archive-tools"><button class="secondary" data-action="export-save">导出存档</button><button class="secondary" data-action="import-save">导入存档</button><span>旧版二维存档独立保留，不会覆盖</span></div><div class="archive-columns"><section><h3>制造蓝图 <small>${save.blueprints.length} / 25</small></h3>${save.blueprints.length?save.blueprints.map(b=>`<article class="archive-row"><div><strong>${esc(b.vehicle.name)}</strong><small>${b.vehicle.stages.length} 级 / ${n(analyzeVehicle(b.vehicle).dv/1000,2)} km/s</small></div><button data-blueprint="${esc(b.id)}" class="secondary" ${view==='flight'?'disabled':''}>载入</button><button class="quiet-button" data-delete-blueprint="${esc(b.id)}" aria-label="删除蓝图">×</button></article>`).join(''):'<p class="empty">在车间保存一份属于你的蓝图。</p>'}<h3>任务记录</h3>${OBJECTIVES.map(o=>`<div class="mission-record"><span>${o.name}</span>${stars(save.records[o.id]?.stars??0)}</div>`).join('')}</section><section><h3>飞行档案 <small>${save.reports.length} / 12</small></h3>${save.reports.length?save.reports.map(r=>`<button class="report-row" data-report="${esc(r.id)}"><span class="report-status ${r.flight.phase==='orbit'?'success':''}">${r.flight.phase==='orbit'?'✓':'↺'}</span><span><strong>${esc(r.flight.vehicle.name)}</strong><small>${r.simulation?'模拟':'正式'} · ${r.flight.objective.name} · ${time(r.flight.time)}</small></span>${stars(r.stars)}</button>`).join(''):'<p class="empty">点火之后，遥测会记录下每一个决定。</p>'}</section></div></section></div>`;
 if(modal==='help')return `<div class="modal-backdrop"><section class="modal manual-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">${close}<p class="eyebrow">ENGINEERING FIELD GUIDE / 工程手册</p><h2 id="modal-title">让制造，真正决定飞行。</h2><div class="manual-grid"><article><span>01</span><h3>几何就是性能</h3><p>直径和长度决定储箱容积；推进剂密度决定燃料质量。材料影响干重、成本与结构耐受，发动机数量影响推力、质量和安装空间。</p></article><article><span>02</span><h3>先让供给成立</h3><p>发动机需要匹配的推进剂。到「质量与供给」查看储箱、主阀与发动机的连接；关闭阀门或使用错误燃料，会导致真实的点火失败。</p></article><article><span>03</span><h3>从离台到入轨</h3><p>真实地球半径 6,371 km，轨道速度约 7.8 km/s。默认自动驾驶执行你的转弯设置，可以接管姿态与节流；重力和阻力损失都会消耗机动预算。</p></article><article><span>04</span><h3>给失败一个解释</h3><p>试验台可比较当前设计、载荷增加与燃料减少。复盘显示真实轨道、损失和失效事件。预算与余量星鼓励你继续优化。</p></article></div><div class="callout">仿真边界：三维牛顿平动、有限姿态控制、旋转大气与简化热/气动/结构模型；并非 CFD、柔性结构或工程认证软件。本版本只聚焦地球入轨。</div><p class="key-help">Space 分级 · F 抛罩 · P 暂停 · M 轨道视角 · H 隐藏界面<br>手动：↑↓ 俯仰 · ←→ 偏航 · W/S 节流。拖动旋转，滚轮缩放。</p><button class="primary wide" data-action="close">回到我的火箭 ${icon('arrow')}</button></section></div>`;
 return '';}
function benchUI(close:string){return `<div class="modal-backdrop"><section class="modal bench-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">${close}<p class="eyebrow">ENGINEERING TEST BENCH / 试验台</p><h2 id="modal-title">用数据，缩短下一次试飞。</h2><p class="modal-description">运行与实际飞行相同的三维模型。验证不会修改蓝图或任务成绩；选中结果后，才会把该方案载入车间。</p><div class="bench-actions"><button class="primary" data-action="bench-stress" ${busy?'disabled':''}>${busy?'计算中…':'工况验证 · 当前 / 重载 / 少油'}</button><button class="secondary" data-action="bench-fuel" ${busy?'disabled':''}>扫描第 ${selected+1} 级加注量</button></div>${bench.length?`<div class="bench-results"><table><thead><tr><th>试验方案</th><th>结果</th><th>近地点</th><th>重力损失</th><th>剩余 Δv</th><th>费用</th><th></th></tr></thead><tbody>${bench.map((b,i)=>{const f=b.flight,grade=missionGrade(f),o=orbitState(f.r,f.v);return `<tr><td>${b.name}</td><td class="${grade.success?'positive':'negative'}">${grade.success?'入轨通过':'未通过'}</td><td>${n(o.peri/1000,0)} km</td><td>${n(f.gravityLoss)} m/s</td><td>${n(deltaV3D(f))} m/s</td><td>${money(vehicleCost(b.vehicle))}</td><td><button class="quiet-button" data-bench-load="${i}">载入 ↗</button></td></tr>`;}).join('')}</tbody></table></div><div class="bench-notes">${bench.map(b=>`<article><strong>${b.name}</strong><p>${b.flight.reason||'尚未满足任务目标。'} 峰值动压 ${(b.flight.maxQ/1000).toFixed(1)} kPa / 最大推力加速度 ${b.flight.maxG.toFixed(2)} g。</p></article>`).join('')}</div>`:`<div class="bench-empty"><span>Δv ≠ 轨道保证</span><p>相同的理论机动预算，也会因飞行程序、推重比与干重分配产生不同结果。</p><small>请选择一个试验，比较你自己的设计。</small></div>`}</section></div>`;}
function reportUI(r:Report3D,close:string){const f=r.flight,o=orbitState(f.r,f.v),grade=missionGrade(f),a=analyzeVehicle(f.vehicle);return `<div class="modal-backdrop"><section class="modal report-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">${close}<p class="eyebrow">POST-FLIGHT ENGINEERING REVIEW / 飞行复盘</p><div class="report-title"><h2 id="modal-title">${grade.success?'轨道，来自你的设计。':'下一次，从这里改进。'}</h2>${stars(grade.stars)}</div><p class="modal-description">${esc(f.reason)} ${r.simulation?'本次为模拟验证，不记录正式任务成绩。':'正式飞行成绩已保存。'}</p><div class="report-kpis"><div><small>近地点 / 远地点</small><strong>${n(o.peri/1000,1)} / ${n(o.apo/1000,1)} <em>km</em></strong></div><div><small>轨道速度</small><strong>${n(o.speed/1000,3)} <em>km/s</em></strong></div><div><small>剩余机动能力</small><strong>${n(deltaV3D(f))} <em>m/s</em></strong></div><div><small>飞行时长</small><strong>${time(f.time)}</strong></div></div><div class="report-layout"><section><h3>高度与速度 · 全程遥测</h3>${flightChart(f)}<div class="loss-breakdown"><div><span>理论总 Δv</span><b>${n(a.dv)} m/s</b></div><div><span>实际发动机累计 Δv</span><b>${n(f.engineDV)} m/s</b></div><div><span>重力损失估计</span><b>${n(f.gravityLoss)} m/s</b></div><div><span>气动损失</span><b>${n(f.dragLoss)} m/s</b></div></div><div class="grade-checks"><div class="${grade.success?'passed':''}">★ 轨道目标 <span>${grade.success?'通过':'未通过'}</span></div><div class="${grade.cost<=f.objective.budget?'passed':''}">★ 制造预算 <span>${money(grade.cost)} / ${money(f.objective.budget)}</span></div><div class="${grade.remaining>=300&&f.maxG<=4?'passed':''}">★ 余量与载荷保护 <span>Δv ≥ 300 m/s · 加速度 ≤ 4 g</span></div></div><div class="callout">${diagnose(f)}</div></section><aside><h3>事件时间线</h3><div class="report-timeline">${f.events.map(e=>`<article class="${e.kind}"><time>T ${time(e.time)}</time><p>${esc(e.text)}</p></article>`).join('')}</div></aside></div><div class="modal-actions"><button class="secondary" data-action="csv">导出遥测 CSV</button><button class="secondary" data-action="save-report-blueprint">保存本次蓝图</button><button class="primary" data-action="return-build">返回车间改型 ${icon('arrow')}</button></div></section></div>`;}
function diagnose(f:Flight3D){if(f.phase==='failed')return esc(f.reason);if(vehicleCost(f.vehicle)>f.objective.budget)return '已经建立轨道。下一步比较更少的发动机、更轻的结构或更合适的储箱尺寸，在预算内保留足够余量。';if(deltaV3D(f)>1800)return '上面级仍有较多余量。可以尝试降低加注量或增加任务载荷；用试验台确认修改没有推高重力损失。';if(f.gravityLoss>2300)return '重力损失较高。尝试调整转弯程序或提高上面级推重比，同时检查低空动压与姿态余量。';return '方案已经通过验证。试着用同一型号交付更重的载荷，或挑战更低的制造费用。';}
function flightChart(f:Flight3D){if(f.samples.length<2)return '<p class="empty">没有足够的遥测样本。</p>';const samples=f.samples,maxH=Math.max(1000,...samples.map(s=>s.altitude)),maxV=Math.max(100,...samples.map(s=>s.speed)),start=samples[0].time,end=samples.at(-1)!.time;const points=(key:'altitude'|'speed',max:number)=>samples.map(s=>`${(40+(s.time-start)/(end-start)*610).toFixed(2)},${(205-s[key]/max*170).toFixed(2)}`).join(' ');return `<div class="chart-legend"><span>高度 · ${n(maxH/1000,0)} km</span><span>速度 · ${n(maxV/1000,2)} km/s</span></div><svg viewBox="0 0 700 240" class="flight-chart" role="img" aria-label="飞行高度与速度时间曲线"><g stroke="#ffffff16">${[35,78,120,163,205].map(y=>`<path d="M40 ${y}H650"/>`).join('')}</g><polyline fill="none" stroke="#eeb280" stroke-width="2" points="${points('altitude',maxH)}"/><polyline fill="none" stroke="#86c6d1" stroke-width="2" points="${points('speed',maxV)}"/><g fill="#8399a4" font-size="10" font-family="monospace"><text x="40" y="230">T ${time(start)}</text><text x="590" y="230">${time(end)}</text></g></svg><p class="chart-note">高度、速度分别按图例峰值归一化；横轴为真实任务时间。</p>`;}
function startFlight(sim:boolean){if(!scene)return;simulation=sim;recorded=false;flight=createFlight3D(save.vehicle,objective());view='flight';speed=1;cameraMode='chase';modal='';scene.setVehicle(flight.vehicle);scene.enterFlight(flight);snapshot();audio.cue();render();}
function returnBuild(){if(flight&&!recorded){if(!flight.reason)stopFlight(flight,'任务由设计师结束。当前遥测已保存。');report=recordFlight(save,flight,simulation);recorded=true;}flight=null;view='workshop';modal='';hiddenUI=false;save.active=undefined;scene?.setVehicle(save.vehicle);scene?.workshop();scene?.setSelected(selected);persist();render();}
function download(filename:string,content:string,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function updateTelemetry(){if(!flight||view!=='flight'||!scene)return;const f=flight,t=telemetry3D(f),o=orbitState(f.r,f.v);if($('mission-clock'))$('mission-clock')!.textContent=`T ${time(f.time)}`;if($('flight-phase'))$('flight-phase')!.textContent=phaseName[f.phase];ui.querySelectorAll('[data-phase]').forEach(el=>el.classList.toggle('active',(el as HTMLElement).dataset.phase===f.phase));
 if($('flight-metrics'))$('flight-metrics')!.innerHTML=`<div class="main-telemetry"><div><small>海拔高度</small><strong>${n(t.altitude/1000,2)}<em>km</em></strong></div><div><small>惯性速度</small><strong>${n(t.speed/1000,3)}<em>km/s</em></strong></div></div><div class="minor-telemetry"><span>垂直速度 <b>${n(t.vertical)} m/s</b></span><span>水平速度 <b>${n(t.horizontal)} m/s</b></span><span>动压 <b class="${t.q>40000?'warning-text':''}">${n(t.q/1000,1)} kPa</b></span><span>推力加速度 <b>${n(t.g,2)} g</b></span><span>推进剂流量 <b>${n(f.currentFlow)} kg/s</b></span><span>喷管摆角 <b>${n(f.currentGimbal,1)}°</b></span></div>`;
 if($('stage-fuel'))$('stage-fuel')!.innerHTML=f.vehicle.stages.map((s,i)=>`<div class="fuel-bar ${i<f.active?'spent':''}"><span>STAGE 0${i+1} ${i<f.active?'已分离':i===f.active?'工作级':'待机'}</span><small>${n(f.fuels[i]/1000,1)} / ${n(fuelMass(s)/1000,1)} t</small><i><b style="width:${f.fuels[i]/Math.max(1,fuelMass(s))*100}%"></b></i></div>`).join('');
 if($('orbit-elements'))$('orbit-elements')!.innerHTML=`<div><small>远地点</small><strong>${n(o.apo/1000,1)} <em>km</em></strong></div><div><small>近地点</small><strong class="${o.peri<140000?'warning-text':''}">${n(o.peri/1000,1)} <em>km</em></strong></div><div><small>剩余 Δv</small><strong>${n(deltaV3D(f))} <em>m/s</em></strong></div><div><small>轨道倾角</small><strong>${n(o.inclination,2)}<em>°</em></strong></div>`;
 if($('events'))$('events')!.innerHTML=f.events.slice(-7).reverse().map(e=>`<article class="${e.kind}"><time>T ${time(e.time)}</time><p>${esc(e.text)}</p></article>`).join('');
 const att=$('attitude') as HTMLCanvasElement|null;if(att){const c=att.getContext('2d')!,pitch=Math.acos(clamp(f.axis.reduce((sum,x,i)=>sum+x*f.r[i]/Math.hypot(...f.r),0),-1,1));c.clearRect(0,0,220,150);c.save();c.beginPath();c.arc(110,73,57,0,Math.PI*2);c.clip();c.fillStyle='#416379';c.fillRect(0,0,220,150);c.fillStyle='#6a5b4b';c.fillRect(0,73-Math.sin(pitch-Math.PI/2)*50,220,150);c.strokeStyle='#c4d4d7';c.lineWidth=1;c.beginPath();c.moveTo(50,73-Math.sin(pitch-Math.PI/2)*50);c.lineTo(170,73-Math.sin(pitch-Math.PI/2)*50);c.stroke();c.restore();c.strokeStyle='#edb380';c.lineWidth=2;c.beginPath();c.moveTo(80,73);c.lineTo(100,73);c.lineTo(110,78);c.lineTo(120,73);c.lineTo(140,73);c.stroke();c.strokeStyle='#6a7d88';c.lineWidth=1;c.beginPath();c.arc(110,73,57,0,Math.PI*2);c.stroke();if($('attitude-label'))$('attitude-label')!.textContent=`${(pitch*180/Math.PI).toFixed(1)}°`;}
 if($('fps'))$('fps')!.textContent=`${Math.round(scene.stats().fps)} FPS`;
}
ui.addEventListener('click',event=>{const el=(event.target as HTMLElement).closest<HTMLButtonElement>('button');if(!el||el.disabled)return;
 if(el.dataset.stage!==undefined){selected=Number(el.dataset.stage);scene?.setSelected(selected);render();return;}
 if(el.dataset.property){panelTab=el.dataset.property;render();return;}
 if(el.dataset.enginePreview){engineDetail=el.dataset.enginePreview;render();return;}
 if(el.dataset.installEngine){mutate(v=>v.stages[selected].engine=el.dataset.installEngine!);modal='';render();notify('发动机已安装。请检查推进剂、安装空间与推重比。');return;}
 if(el.dataset.partsCategory){partsCategory=el.dataset.partsCategory;render();return;}
 if(el.dataset.tankReplace||el.dataset.tankAdd){try{mutate(v=>fitTank(v.stages[selected],(el.dataset.tankReplace||el.dataset.tankAdd)!,!!el.dataset.tankReplace));}catch(error){notify((error as Error).message);}return;}
 if(el.dataset.removeTank!==undefined){try{mutate(v=>removeTank(v.stages[selected],Number(el.dataset.removeTank)));}catch(error){notify((error as Error).message);}return;}
 if(el.dataset.moveTank!==undefined){const i=Number(el.dataset.moveTank);mutate(v=>{const a=v.stages[selected].tankModules!;[a[i-1],a[i]]=[a[i],a[i-1]];});return;}
 if(el.dataset.fairingPart){mutate(v=>{v.fairingModel=el.dataset.fairingPart;v.fairing=true;});return;}
 if(el.dataset.structurePart){mutate(v=>{const s=v.stages[selected];if(el.dataset.structurePart==='adapter')s.adapter=!s.adapter;else s.coupling=el.dataset.structurePart as 'separator'|'fixed';});return;}
 if(el.dataset.engine){mutate(v=>v.stages[selected].engine=el.dataset.engine!);return;}
 if(el.dataset.count){mutate(v=>v.stages[selected].engines=clamp(v.stages[selected].engines+Number(el.dataset.count),1,9));return;}
 if(el.dataset.camera){cameraMode=el.dataset.camera;scene?.setCameraMode(cameraMode,flight??undefined);render();return;}
 if(el.dataset.warp){speed=Number(el.dataset.warp);render();return;}
 if(el.dataset.blueprint){const b=save.blueprints.find(b=>b.id===el.dataset.blueprint);if(b&&view==='workshop'){mutate(v=>Object.assign(v,structuredClone(b.vehicle)));modal='';render();}return;}
 if(el.dataset.deleteBlueprint){save.blueprints=save.blueprints.filter(b=>b.id!==el.dataset.deleteBlueprint);persist();render();return;}
 if(el.dataset.report){report=save.reports.find(r=>r.id===el.dataset.report)!;modal='report';render();return;}
 if(el.dataset.benchLoad!==undefined){const b=bench[Number(el.dataset.benchLoad)];if(b){mutate(v=>Object.assign(v,structuredClone(b.vehicle)));modal='';render();notify('试验方案已载入，原方案可撤销恢复。');}return;}
 switch(el.dataset.action){
 case'workshop':if(view==='flight'&&!flight?.reason){notify('飞行正在进行。可暂停查看档案，或先终止飞行再返回制造车间。');break;}if(view==='flight')returnBuild();else{modal='';render();}break;
 case'flight':modal='';render();break;
 case'brief':if(view==='workshop'){modal='brief';render();}break;
 case'archive':modal='archive';render();break;
 case'help':modal='help';render();break;
 case'close':if(!busy){modal='';render();}break;
 case'guidance':modal='guidance';render();break;
 case'audio':save.muted=!save.muted;audio.enable(!save.muted);persist();render();break;
 case'cutaway':cutaway=!cutaway;scene?.setCutaway(cutaway);render();break;
 case'reset-camera':scene?.workshop();break;
 case'engine-close':scene?.inspectEngine();break;
 case'add-stage':if(save.vehicle.stages.length<3)mutate(v=>v.stages.push(newStage(true)));break;
 case'delete-stage':if(save.vehicle.stages.length>1)mutate(v=>v.stages.splice(selected,1));break;
 case'match-fuel':mutate(v=>{delete v.stages[selected].tankModules;v.stages[selected].fuel=engineSpec(v.stages[selected]).fuel;});notify('储箱已按目标推进剂改装，标准件标记转为定制。');break;
 case'engine-library':engineDetail=save.vehicle.stages[selected].engine;modal='engines';render();break;
 case'parts-library':partsCategory='tanks';modal='parts';render();break;
 case'starter':mutate(v=>Object.assign(v,defaultVehicle()));notify('标准件参考构型已载入，原设计可撤销恢复。');break;
 case'export-engines':download('meridian-real-engines.json',JSON.stringify(REAL_ENGINES,null,2));break;
 case'valve':mutate(v=>v.stages[selected].valve=!v.stages[selected].valve);break;
 case'undo':if(undo.length){redo.push(structuredClone(save.vehicle));save.vehicle=undo.pop()!;selected=0;scene?.setVehicle(save.vehicle);persist();render();}break;
 case'redo':if(redo.length){undo.push(structuredClone(save.vehicle));save.vehicle=redo.pop()!;selected=0;scene?.setVehicle(save.vehicle);persist();render();}break;
 case'blueprint':save.blueprints.unshift({id:crypto.randomUUID(),vehicle:structuredClone(save.vehicle),date:new Date().toISOString()});save.blueprints=save.blueprints.slice(0,25);persist();notify('当前蓝图已保存至工程档案。');break;
 case'launch-sim':startFlight(true);break;
 case'launch-live':startFlight(false);break;
 case'pause':if(flight){flight.paused=!flight.paused;snapshot();render();}break;
 case'separate':if(flight&&!flight.paused)separate3D(flight);break;
 case'fairing':if(flight&&!flight.paused)jettisonFairing(flight);break;
 case'abort':if(flight){stopFlight(flight,'任务由设计师终止。可从遥测检查设计与程序。');finishUI();}break;
 case'report':if(report){modal='report';render();}break;
 case'return-build':returnBuild();break;
 case'cinematic':hiddenUI=!hiddenUI;render();break;
 case'bench':modal='bench';render();break;
 case'bench-stress':runBench(false);break;
 case'bench-fuel':runBench(true);break;
 case'save-report-blueprint':if(report){save.blueprints.unshift({id:crypto.randomUUID(),vehicle:structuredClone(report.flight.vehicle),date:new Date().toISOString()});save.blueprints=save.blueprints.slice(0,25);persist();notify('本次飞行蓝图已保存。');}break;
 case'csv':if(report){const samples=report.flight.samples;download('meridian-flight-telemetry.csv','time_s,altitude_m,inertial_speed_m_s,vertical_m_s,horizontal_m_s,mass_kg,propellant_kg,dynamic_pressure_pa,thrust_g,temperature_k,apogee_m,perigee_m\n'+samples.map(s=>[s.time,s.altitude,s.speed,s.vertical,s.horizontal,s.mass,s.fuel,s.q,s.g,s.heat,s.apo,s.peri].map(x=>Number.isFinite(x)?x.toFixed(4):'').join(',')).join('\n'),'text/csv');}break;
 case'export-save':snapshot();download('meridian-3d-save.json',JSON.stringify(save));break;
 case'import-save':if(view==='flight'){notify('请先结束当前飞行，再导入存档。');break;}importSave();break;
 }
});
ui.addEventListener('change',event=>{const el=event.target as HTMLInputElement,id=el.id;
 if(id==='objective'){save.objective=el.value;persist();render();return;}
 if(id==='autopilot'&&flight){flight.autopilot=el.checked;if(!el.checked){const p=Math.acos(clamp(flight.axis.reduce((sum,x,i)=>sum+x*flight!.r[i]/Math.hypot(...flight!.r),0),-1,1));flight.manualPitch=p;flight.command=flight.throttle;}render();return;}
 if(view!=='workshop')return;
 if(['vehicle-name','payload','fairing','diameter','tank-length','fill','material','fuel-type','fins','turn-start','turn-end','max-g','auto-stage'].includes(id))mutate(v=>{const s=v.stages[selected];switch(id){case'vehicle-name':v.name=el.value.trim()||'未命名飞行器';break;case'payload':v.payload=Number(el.value);break;case'fairing':v.fairing=el.checked;break;case'diameter':delete s.tankModules;s.diameter=Number(el.value);break;case'tank-length':delete s.tankModules;s.tankLength=Number(el.value);break;case'fill':s.fill=Number(el.value)/100;break;case'material':s.material=el.value as typeof s.material;break;case'fuel-type':delete s.tankModules;s.fuel=el.value as typeof s.fuel;break;case'fins':s.fins=el.checked;break;case'turn-start':v.guidance.turnStart=Number(el.value);break;case'turn-end':v.guidance.turnEnd=Number(el.value);break;case'max-g':v.guidance.maxG=Number(el.value);break;case'auto-stage':v.guidance.autoStage=el.checked;}});
});
ui.addEventListener('input',event=>{const el=event.target as HTMLInputElement;if(el.id==='engine-search'){const q=el.value.toLowerCase();ui.querySelectorAll<HTMLElement>('[data-engine-preview]').forEach(card=>card.hidden=!card.textContent!.toLowerCase().includes(q));return;}if(!flight||flight.autopilot)return;if(el.id==='throttle')flight.command=Number(el.value)/100;if(el.id==='pitch')flight.manualPitch=Number(el.value)*Math.PI/180;if(el.id==='yaw')flight.manualYaw=Number(el.value)*Math.PI/180;});
function importSave(){const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{const file=input.files?.[0];if(!file)return;if(file.size>12e6){notify('存档超过 12 MB 上限。');return;}try{save=parse3D(await file.text());selected=0;scene?.setVehicle(save.vehicle);undo=[];redo=[];restoreFlight();persist();render();notify('3D 存档已恢复。');}catch{notify('存档无效或版本不兼容，当前进度保持不变。');}};input.click();}
function runBench(sweep:boolean){if(busy)return;busy=true;render();setTimeout(()=>{try{const base=structuredClone(save.vehicle),variants:{name:string;vehicle:Vehicle}[]=[];if(sweep){for(const factor of [.55,.7,.85,1]){const d=structuredClone(base);d.stages[selected].fill=factor;variants.push({name:`第 ${selected+1} 级 ${factor*100}% 加注`,vehicle:d});}}else {const heavy=structuredClone(base);heavy.payload=Math.min(20000,Math.round(base.payload*1.2));const lean=structuredClone(base);lean.stages.forEach(s=>s.fill=Math.max(.1,s.fill*.9));variants.push({name:'当前方案',vehicle:base},{name:'载荷 +20%',vehicle:heavy},{name:'全级加注 −10%',vehicle:lean});}bench=variants.map(v=>({...v,flight:simulate3D(v.vehicle,objective())}));}finally{busy=false;render();}},30);}
function finishUI(){if(!flight)return;if(!recorded){report=recordFlight(save,flight,simulation);recorded=true;audio.cue(flight.phase==='orbit');snapshot();}render();}
function restoreFlight(){if(save.active){flight=save.active.flight;flight.paused=true;simulation=save.active.simulation;recorded=save.active.recorded;report=recorded?save.reports[0]??null:null;view='flight';scene?.setVehicle(flight.vehicle);scene?.enterFlight(flight);}else {flight=null;view='workshop';scene?.workshop();}}
window.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes((e.target as HTMLElement).tagName))return;if(e.key==='Escape'&&modal&&!busy){modal='';render();return;}if(view==='workshop'&&e.key.toLowerCase()==='h'&&!modal){hiddenUI=!hiddenUI;render();return;}if(view!=='flight'||!flight||modal)return;const key=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(key))e.preventDefault();if(key==='p'){flight.paused=!flight.paused;render();}if(key==='m'){cameraMode=cameraMode==='orbit'?'chase':'orbit';scene?.setCameraMode(cameraMode,flight);render();}if(key==='h'){hiddenUI=!hiddenUI;render();}if(!flight.paused){if(e.code==='Space')separate3D(flight);if(key==='f')jettisonFairing(flight);if(!flight.autopilot){if(key==='w')flight.command=clamp(flight.command+.05,0,1);if(key==='s')flight.command=clamp(flight.command-.05,0,1);if(key==='arrowup')flight.manualPitch=clamp(flight.manualPitch-.025,-.2,1.75);if(key==='arrowdown')flight.manualPitch=clamp(flight.manualPitch+.025,-.2,1.75);if(key==='arrowleft')flight.manualYaw=clamp(flight.manualYaw-.02,-.5,.5);if(key==='arrowright')flight.manualYaw=clamp(flight.manualYaw+.02,-.5,.5);}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&flight){flight.paused=true;snapshot();render();}});window.addEventListener('pagehide',snapshot);
let previous=performance.now(),lastUI=0,lastSave=0;
function frame(now:number){const dt=Math.min(.1,Math.max(0,(now-previous)/1000));previous=now;if(scene){if(flight&&view==='flight'){if(!modal)stepFlight3D(flight,dt*speed);scene.updateFlight(flight,now/1000);audio.update(flight.throttle,altitude3D(flight),flight.paused||!!modal||flight.phase==='failed');if(flight.reason&&!recorded)finishUI();if(now-lastUI>220){updateTelemetry();lastUI=now;}if(now-lastSave>2500){snapshot();lastSave=now;}}scene.render();if(view==='workshop'&&now-lastUI>500){if($('fps'))$('fps')!.textContent=`${Math.round(scene.stats().fps)} FPS`;lastUI=now;}}requestAnimationFrame(frame);}
if(scene){restoreFlight();render();requestAnimationFrame(frame);}
function tankAssemblyUI(){const s=save.vehicle.stages[selected],modules=assembledTanks(s);return `<div class="section-heading"><span>储箱与连接件</span><small>STANDARD PARTS</small></div><div class="tank-stack">${modules.length?modules.map((p,i)=>`<div><span class="tank-number">${i+1}</span><span><strong>${p.name}</strong><small>Ø ${p.diameter} m · ${p.length} m · ${FUELS[p.fuel].name}</small></span><button data-move-tank="${i}" ${i===0?'disabled':''} aria-label="上移储箱">↑</button><button data-remove-tank="${i}" ${modules.length===1?'disabled':''} aria-label="移除储箱">×</button></div>`).join(''):`<div class="custom-part"><span>定制储箱</span><small>Ø ${n(s.diameter,1)} × ${n(s.tankLength,1)} m</small></div>`}</div><button class="library-open" data-action="parts-library">标准零件库 <span>储箱 · 分离器 · 适配器 · 整流罩 ↗</span></button><div class="connection-status"><span>${s.coupling==='fixed'?'固定连接':'级间分离器'} / ${s.adapter?'异径适配器已安装':'直径直连'}</span></div>`;}
function engineLibraryUI(close:string){const selectedEngine=ENGINES3D.find(e=>e.id===engineDetail)??REAL_ENGINES[0],d=selectedEngine.provenance;const rows:[string,keyof NonNullable<typeof d>['published'],string,number][]=[['海平面推力','sea','kN',.001],['真空推力','vac','kN',.001],['海平面比冲','ispSea','s',1],['真空比冲','ispVac','s',1],['发动机本体 / 模型安装质量','mass','kg',1],['喷口直径 / 模型包络','diameter','m',1],['节流下限 / 模型选取值','minThrottle','%',100]];
 return `<div class="modal-backdrop"><section class="modal engine-library" role="dialog" aria-modal="true" aria-labelledby="modal-title">${close}<p class="eyebrow">REAL-WORLD PROPULSION / 真实发动机目录</p><h2 id="modal-title">把真实的发动机，装进你的设计。</h2><p class="modal-description">${REAL_ENGINES.length} 型参考配置。公开数据与仿真假设分列，保留年份、版本和工作点。价格全部为游戏数值，几何为程序化近似，非厂商 CAD。</p><div class="engine-library-layout"><aside><input id="engine-search" type="search" placeholder="搜索型号、制造商、推进剂…" aria-label="搜索发动机"><div class="catalogue-list">${REAL_ENGINES.map(e=>`<button data-engine-preview="${e.id}" class="${e.id===selectedEngine.id?'selected':''}"><span><strong>${e.name}</strong><small>${e.provenance!.country} · ${e.provenance!.manufacturer}</small></span><em>${FUELS[e.fuel].name}</em></button>`).join('')}</div></aside><section class="engine-details"><div class="engine-detail-heading"><span>${d?`${d.country} / ${d.manufacturer}`:'MERIDIAN / 原型发动机'}</span><h3>${selectedEngine.name}</h3><p>${selectedEngine.role} · ${FUELS[selectedEngine.fuel].name}</p></div>${d?`<div class="source-scope"><strong>资料口径</strong><p>${esc(d.configuration)}</p><small>核对日期 ${d.checkedAt} · 原源不可读时已明确标注</small></div>`:''}<table class="engine-data-table"><thead><tr><th>参数</th><th>资料记录值</th><th>飞行模型采用</th></tr></thead><tbody>${rows.map(([label,key,unit,scale])=>{const published=d?.published[key],model=selectedEngine[key] as number;return `<tr><td>${label}</td><td class="${published===undefined?'estimated':'verified'}">${published===undefined?'未逐项核实':n(published*scale,key==='diameter'?3:1)+' '+unit}</td><td>${published===undefined?'≈ ':''}${n(model*scale,key==='diameter'?3:1)} ${unit}</td></tr>`;}).join('')}</tbody></table><div class="source-explanation"><strong>仿真补全与口径限制</strong><p>${esc(d?.notes??'原型数据，不对应真实厂商型号。')}</p><p>摆角、点火次数、安装接口、制造费用、供给动态及未核实的性能字段属于游戏模型，不能视为真实硬件保证。</p>${d?.verification?`<p class="verification-note">${esc(d.verification)}</p>`:''}</div><div class="source-links"><strong>公开资料</strong>${d?.sources.map(source=>`<a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">${esc(source.title)} ↗</a>`).join('')??''}</div><div class="engine-install"><span>安装到第 ${selected+1} 级<br><small>安装后保留原储箱，需重新检查燃料兼容性</small></span><button class="primary" data-install-engine="${selectedEngine.id}">安装发动机 ${icon('arrow')}</button></div></section></div><div class="catalogue-footer"><span>不是全世界发动机的完整数据库；当前目录按可核对资料逐步扩充。</span><button class="quiet-button" data-action="export-engines">导出带来源的发动机数据 JSON</button></div></section></div>`;
}
function partsLibraryUI(close:string){const s=save.vehicle.stages[selected],modules=assembledTanks(s);return `<div class="modal-backdrop"><section class="modal parts-library" role="dialog" aria-modal="true" aria-labelledby="modal-title">${close}<p class="eyebrow">MODULAR ASSEMBLY / 标准件装配</p><h2 id="modal-title">选择部件，而不只是填写参数。</h2><p class="modal-description">当前安装位置：第 ${selected+1} 级。储箱、结构件和整流罩为游戏内标准件，不代表真实厂家存在统一通用接口。</p><div class="parts-category">${[['tanks','推进剂储箱'],['structure','级间与适配'],['fairings','载荷整流罩']].map(([id,label])=>`<button data-parts-category="${id}" class="${partsCategory===id?'selected':''}">${label}</button>`).join('')}</div><div class="parts-grid">${partsCategory==='tanks'?TANK_PARTS.map(p=>{const compatible=!modules.length||modules[0].fuel===p.fuel&&modules[0].diameter===p.diameter;return `<article class="part-card"><span class="part-silhouette tank-symbol" style="--part-color:${FUELS[p.fuel].color}"></span><div><h3>${p.name}</h3><span class="part-interface">Ø ${p.diameter} m / ${p.length} m / ${FUELS[p.fuel].name}</span><p>${p.description}</p><div class="part-actions"><button class="secondary" data-tank-replace="${p.id}">替换本级储箱</button><button class="primary" data-tank-add="${p.id}" ${!compatible?'disabled':''}>${compatible?'追加一段 ＋':'接口不兼容'}</button></div></div></article>`;}).join(''):partsCategory==='structure'?`<article class="part-card"><span class="part-silhouette ring-symbol"></span><div><h3>S-RING / 级间分离器</h3><span class="part-interface">分级连接 · 85 kg 游戏质量</span><p>释放空级，并保持剩余飞行器的速度连续。未安装时，自动分级不能丢弃干重。</p><button class="${s.coupling!=='fixed'?'secondary':'primary'}" data-structure-part="separator">${s.coupling!=='fixed'?'已安装 · 重新选择':'安装分离器'}</button></div></article><article class="part-card"><span class="part-silhouette ring-symbol fixed-symbol"></span><div><h3>FIX-RING / 固定连接环</h3><span class="part-interface">整体连接 · 不支持分离</span><p>保留结构连接。适合整体飞行方案，但会阻止该级分离，空箱与发动机仍计入质量。</p><button class="secondary" data-structure-part="fixed">${s.coupling==='fixed'?'已安装':'改为固定连接'}</button></div></article><article class="part-card"><span class="part-silhouette adapter-symbol"></span><div><h3>A-CONE / 异径适配器</h3><span class="part-interface">上下不同口径 · 60 kg 游戏质量</span><p>连接不同直径的火箭级。拆除后，口径不同的级间接口会在制造检查中报错。</p><button class="${s.adapter?'secondary':'primary'}" data-structure-part="adapter">${s.adapter?'拆除适配器':'安装适配器'}</button></div></article>`:FAIRING_PARTS.map(p=>`<article class="part-card"><span class="part-silhouette fairing-symbol"></span><div><h3>${p.name}</h3><span class="part-interface">Ø ${p.diameter} m / ${p.height} m / ${p.mass} kg</span><p>保护载荷并降低迎风阻力。安装改变几何、质量与费用；抛罩后移除该部件质量。</p><button class="${save.vehicle.fairingModel===p.id?'secondary':'primary'}" data-fairing-part="${p.id}">${save.vehicle.fairingModel===p.id?'已安装':'安装整流罩'}</button></div></article>`).join('')}</div><div class="callout">同一级储箱仅能堆叠相同口径、相同推进剂，最多 5 段、总筒段长度不超过 25 m；不同级通过分离器和异径适配器连接。添加的储箱端盖与连接质量也会进入仿真。</div></section></div>`;}
